-- CloudBackupSelectionRepository.estimate
SELECT
  count(*)::int AS total,
  count(*) FILTER (
    WHERE
      (
        (
          s.favorites
          AND a."isFavorite"
        )
        OR EXISTS (
          SELECT
            1
          FROM
            public.album_asset aa
            JOIN public.album al ON al.id = aa."albumId"
            AND al."deletedAt" IS NULL
          WHERE
            aa."assetId" = a.id
            AND aa."albumId" = ANY (s."albumIds")
        )
        OR EXISTS (
          SELECT
            1
          FROM
            public.album_asset aa
            JOIN public.album al ON al.id = aa."albumId"
            AND al."deletedAt" IS NULL
            JOIN public.album_closure c ON c.id_descendant = aa."albumId"
            JOIN public.album collection ON collection.id = c.id_ancestor
            AND collection."deletedAt" IS NULL
            AND collection.kind = 'collection'
          WHERE
            aa."assetId" = a.id
            AND c.id_ancestor = ANY (s."collectionIds")
        )
        OR EXISTS (
          SELECT
            1
          FROM
            public.asset_face f
          WHERE
            f."assetId" = a.id
            AND f."personGroupId" = ANY (s."personIds")
            AND f."deletedAt" IS NULL
            AND f."isVisible" IS TRUE
        )
        OR EXISTS (
          SELECT
            1
          FROM
            public.tag_asset ta
            JOIN public.tag_closure tc ON tc.id_descendant = ta."tagId"
          WHERE
            ta."assetId" = a.id
            AND tc.id_ancestor = ANY (s."tagIds")
        )
        OR EXISTS (
          SELECT
            1
          FROM
            unnest(s.folders) AS folder (path)
          WHERE
            folder.path <> ''
            AND a."originalPath" LIKE replace(
              replace(replace(folder.path, '\', '\\'), '%', '\%'),
              '_',
              '\_'
            ) || '/%'
        )
        OR EXISTS (
          SELECT
            1
          FROM
            jsonb_array_elements(s."dateRanges") AS chosen (range)
          WHERE
            CASE chosen.range ->> 'kind'
              WHEN 'between' THEN (a."localDateTime" AT TIME ZONE 'UTC')::date BETWEEN (chosen.range ->> 'from')::date AND (chosen.range ->> 'to')::date
              WHEN 'recent' THEN (a."localDateTime" AT TIME ZONE 'UTC') >= ($1::timestamptz AT TIME ZONE 'UTC') - make_interval(months => (chosen.range ->> 'months')::int)
              ELSE false
            END
        )
      )
  )::int AS selected
FROM
  public.asset a
  CROSS JOIN (
    SELECT
      $2::uuid[] AS "albumIds",
      $3::uuid[] AS "collectionIds",
      $4::uuid[] AS "personIds",
      $5::uuid[] AS "tagIds",
