-- CloudBackupSelectionRepository.recordIncluded
UPDATE public.cloud_backup_decision_account account
SET
  "includedOriginals" = (
    SELECT
      count(*)::int
    FROM
      public.cloud_backup_manifest_entry entry
      JOIN public.cloud_backup_decision_asset decision ON decision."runId" = account."runId"
      AND decision."assetId" = entry."assetId"
      AND decision.reason = 'included'
    WHERE
      entry."manifestId" = $1::uuid
      AND entry.role = 'original'
      AND decision."ownerId" = account."userId"
  )
WHERE
  account."runId" = $2::uuid
  AND account."includedOriginals" IS NULL

-- CloudBackupSelectionRepository.getInventoryPage
SELECT
  a.id,
  a."ownerId",
  a."originalFileName",
  exists (
    select
      1
    from
      asset_lock
    where
      asset_lock."assetId" = "a"."id"
  ) AS locked,
  decision.reason
FROM
  public.asset a
  LEFT JOIN public.cloud_backup_decision_asset decision ON decision."runId" = $1::uuid
  AND decision."assetId" = a.id
WHERE
  a.status = ANY ($2::assets_status_enum[])
  AND a."isExternal" = false
  AND (
    $3::uuid IS NULL
    OR a.id > $4::uuid
  )
  AND (
    $5::uuid IS NULL
    OR a."ownerId" = $6::uuid
  )
ORDER BY
  a.id
LIMIT
  $7

